import { Component, computed, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { catchError, map, of, switchMap, tap } from 'rxjs';
import { ApiService } from '../core/api.service';
import { BookingService } from '../core/booking.service';
import { showDate } from '../core/dates';
import { Movie, Screening } from '../core/models';
import {
  COUCH_ROW,
  MAX_SEATS,
  ROW_COUNT,
  compareKeys,
  describeShort,
  keyOf,
  parseKey,
  seatCount,
  seatIds,
  totalSeats,
} from '../core/seats';
import { ToastService } from '../core/toast.service';

type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

interface Cell {
  kind: 'seat' | 'couch' | 'aisle';
  key: string;
  col: number;
  colEnd: number;
  gridColumn: string;
}

interface RowLayout {
  row: number;
  cells: Cell[];
}

const LEGEND: { state: SeatState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

/** Grid column of a seat column: column 1 is grid column 2 (1 is the left row label). */
function gridColumn(col: number): number {
  if (col <= 4) return col + 1;
  if (col <= 20) return col + 2;
  return col + 3;
}

function buildLayout(): RowLayout[] {
  const rows: RowLayout[] = [];
  for (let row = 1; row <= ROW_COUNT; row++) {
    const cells: Cell[] = [
      { kind: 'aisle', key: '', col: 0, colEnd: 0, gridColumn: '6' },
      { kind: 'aisle', key: '', col: 0, colEnd: 0, gridColumn: '23' },
    ];
    if (row === COUCH_ROW) {
      for (let col = 1; col <= 24; col += 2) {
        cells.push({
          kind: 'couch',
          key: keyOf(row, col),
          col,
          colEnd: col + 1,
          gridColumn: `${gridColumn(col)} / span 2`,
        });
      }
    } else {
      for (let col = row <= 10 ? 5 : 1; col <= 24; col++) {
        cells.push({
          kind: 'seat',
          key: keyOf(row, col),
          col,
          colEnd: col,
          gridColumn: String(gridColumn(col)),
        });
      }
    }
    rows.push({ row, cells });
  }
  return rows;
}

const LAYOUT = buildLayout();

@Component({
  selector: 'app-seat-map',
  imports: [MatButtonModule],
  templateUrl: './seat-map.html',
  styleUrl: './seat-map.scss',
})
export class SeatMap {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly booking = inject(BookingService);
  private readonly toast = inject(ToastService);

  protected readonly legend = LEGEND;
  private readonly data = signal<{ screening: Screening; movie: Movie } | null>(null);

  protected readonly subtitle = computed(() => {
    const s = this.data()?.screening;
    return s ? `Show Date: ${showDate(s.date, s.time)}` : '';
  });

  private readonly selectedKeys = computed(() => {
    const b = this.booking.booking();
    const s = this.data()?.screening;
    return b && s && !b.paid && b.screeningId === s.id ? b.items : [];
  });

  protected readonly rows = computed(() => {
    const screening = this.data()?.screening;
    if (!screening) return [];
    const occupied = new Set(screening.occupiedSeats);
    const selected = new Set(this.selectedKeys());
    return LAYOUT.map((r) => ({
      row: r.row,
      cells: r.cells.map((cell) => ({ cell, state: this.stateOf(cell, occupied, selected) })),
    }));
  });

  protected readonly selectedCount = computed(() => totalSeats(this.selectedKeys()));

  protected readonly selectedRows = computed(() => {
    const byRow = new Map<number, string[]>();
    for (const key of [...this.selectedKeys()].sort(compareKeys)) {
      const row = parseKey(key).row;
      byRow.set(row, [...(byRow.get(row) ?? []), describeShort(key)]);
    }
    return [...byRow].map(([row, seats]) => ({ row, text: seats.join(', ') }));
  });

  constructor() {
    inject(ActivatedRoute)
      .paramMap.pipe(
        map((params) => params.get('id') ?? ''),
        tap(() => this.data.set(null)),
        switchMap((id) =>
          this.api.loadScreening(id).pipe(catchError(() => of(null))),
        ),
        takeUntilDestroyed(),
      )
      .subscribe((result) => {
        if (!result) {
          this.router.navigateByUrl('/');
          return;
        }
        const current = this.booking.booking();
        if (!current || current.paid || current.screeningId !== result.screening.id) {
          this.booking.start(result.screening.id);
        }
        this.data.set(result);
      });
  }

  private stateOf(cell: Cell, occupied: Set<string>, selected: Set<string>): SeatState {
    if (seatIds(cell.key).some((id) => occupied.has(id))) return 'unavailable';
    if (selected.has(cell.key)) return 'selected';
    const { row, col } = parseKey(cell.key);
    return cell.kind === 'seat' && row === 1 && col >= 10 && col <= 15 ? 'accessible' : 'available';
  }

  protected toggle(cell: Cell, state: SeatState): void {
    if (state === 'unavailable') return;
    const items = this.selectedKeys();
    if (state === 'selected') {
      this.booking.setItems(items.filter((k) => k !== cell.key));
      return;
    }
    if (totalSeats(items) + seatCount(cell.key) > MAX_SEATS) {
      this.toast.show('Maximum 10 seats per booking');
      return;
    }
    this.booking.setItems([...items, cell.key]);
  }

  protected cancel(): void {
    this.booking.clear();
    this.router.navigateByUrl('/');
  }

  protected next(): void {
    const screening = this.data()?.screening;
    if (screening && this.selectedKeys().length > 0) {
      this.router.navigate(['/screenings', screening.id, 'summary']);
    }
  }

  protected hasSelection(): boolean {
    return this.selectedKeys().length > 0;
  }
}

@if (data(); as d) {
  <div class="page">
    <h1 class="title" data-testid="seat-map-title">Choose your seats</h1>
    <p class="subtitle" data-testid="seat-map-subtitle">{{ subtitle() }}</p>

    <div class="auditorium">
      <p class="limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>
      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (r of rows(); track r.row) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="r.row">
            <span class="row-label left" data-testid="row-label-left" [attr.data-row]="r.row">{{ r.row }}</span>
            @for (c of r.cells; track $index) {
              @switch (c.cell.kind) {
                @case ('aisle') {
                  <div class="aisle" data-testid="aisle" [attr.data-row]="r.row" [style.grid-column]="c.cell.gridColumn"></div>
                }
                @case ('couch') {
                  <button
                    type="button"
                    class="seat couch"
                    data-testid="couch"
                    [attr.data-row]="r.row"
                    [attr.data-column-start]="c.cell.col"
                    [attr.data-column-end]="c.cell.colEnd"
                    [attr.data-state]="c.state"
                    [attr.aria-disabled]="c.state === 'unavailable'"
                    [style.grid-column]="c.cell.gridColumn"
                    (click)="toggle(c.cell, c.state)"
                  >{{ c.cell.col }}-{{ c.cell.colEnd }}</button>
                }
                @default {
                  <button
                    type="button"
                    class="seat"
                    data-testid="seat"
                    [attr.data-row]="r.row"
                    [attr.data-column]="c.cell.col"
                    [attr.data-state]="c.state"
                    [attr.aria-disabled]="c.state === 'unavailable'"
                    [style.grid-column]="c.cell.gridColumn"
                    (click)="toggle(c.cell, c.state)"
                  >{{ c.cell.col }}</button>
                }
              }
            }
            <span class="row-label right" data-testid="row-label-right" [attr.data-row]="r.row">{{ r.row }}</span>
          </div>
        }
      </div>
    </div>

    <div class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <span class="legend-item" data-testid="legend-item" [attr.data-state]="item.state">
          <span class="swatch" [attr.data-state]="item.state"></span>{{ item.label }}
        </span>
      }
    </div>

    <div class="selected-seats" data-testid="selected-seats">
      <div data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</div>
      @for (line of selectedRows(); track line.row) {
        <div data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.text }}</div>
      }
    </div>

    <div class="actions">
      <button mat-stroked-button type="button" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button
        mat-flat-button
        type="button"
        data-testid="continue-button"
        [disabled]="!hasSelection()"
        (click)="next()"
      >
        Continue
      </button>
    </div>
  </div>
}

