import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { BookingService } from '../core/booking.service';
import { SeatMap } from './seat-map';

describe('SeatMap', () => {
  beforeEach(() => sessionStorage.clear());

  async function setup() {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([{ path: 'screenings/:id/seats', component: SeatMap }]),
        provideNativeDateAdapter(),
      ],
    });
    const http = TestBed.inject(HttpTestingController);
    const fixture = TestBed.createComponent(SeatMap);
    fixture.componentRef.changeDetectorRef.detectChanges();
    return { http, fixture };
  }

  it('draws the auditorium and handles selection', async () => {
    TestBed.configureTestingModule({
      providers: [
        provideHttpClient(),
        provideHttpClientTesting(),
        provideRouter([]),
        provideNativeDateAdapter(),
      ],
    });
    const http = TestBed.inject(HttpTestingController);
    const router = TestBed.inject((await import('@angular/router')).Router);
    router.resetConfig([{ path: 'screenings/:id/seats', component: SeatMap }]);
    const harness = await import('@angular/router/testing').then((m) => m.RouterTestingHarness);
    const h = await harness.create();
    const promise = h.navigateByUrl('/screenings/1/seats', SeatMap);
    await Promise.resolve();
    http
      .expectOne('http://localhost:3000/screenings/1')
      .flush({ id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: ['R3C7', 'R15C5', 'R15C6'] });
    await Promise.resolve();
    http.expectOne('http://localhost:3000/movies/1').flush({ id: 1, title: 'X', genre: 'Y', runtimeMinutes: 1, format: 'PL dubbing' });
    await promise;
    h.detectChanges();
    const el: HTMLElement = h.fixture.nativeElement;
    const q = (id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

    expect(q('seat-row').length).toBe(15);
    expect(q('seat').length).toBe(296);
    expect(q('couch').length).toBe(12);
    expect(q('aisle').length).toBe(30);
    expect(q('row-label-left').length).toBe(15);
    expect(q('row-label-right').length).toBe(15);
    expect(q('seat').filter((s) => s.dataset['state'] === 'accessible').length).toBe(6);
    expect(q('seat-map-subtitle')[0].textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
    expect(q('seat').find((s) => s.dataset['row'] === '3' && s.dataset['column'] === '7')?.dataset['state']).toBe('unavailable');
    expect(q('couch').find((c) => c.dataset['columnStart'] === '5')?.dataset['state']).toBe('unavailable');

    const seat = (row: number, col: number) =>
      q('seat').find((s) => s.dataset['row'] === `${row}` && s.dataset['column'] === `${col}`)!;
    seat(7, 12).click();
    seat(7, 11).click();
    q('couch').find((c) => c.dataset['columnStart'] === '1')!.click();
    h.detectChanges();
    expect(q('selected-seats-count')[0].textContent).toBe('Selected seats: 4');
    expect(q('selected-seats-row').map((r) => r.textContent)).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);
    expect(getComputedStyle(seat(7, 12)).backgroundColor).toBeTruthy();

    // fill to the cap, then one more must be ignored
    for (const c of [3, 5, 7]) q('couch').find((x) => x.dataset['columnStart'] === `${c + 2 > 7 ? 7 : c}`)?.click();
    h.detectChanges();
    const count = () => Number(q('selected-seats-count')[0].textContent!.replace(/\D/g, ''));
    for (let col = 10; col < 24 && count() < 10; col++) seat(8, col).click();
    h.detectChanges();
    expect(count()).toBe(10);
    seat(9, 10).click();
    h.detectChanges();
    expect(count()).toBe(10);
    expect(TestBed.inject(BookingService).booking()?.items.length).toBeGreaterThan(0);
  });
});
